    return float(EXIT_X_MIN)

def build_agent(sandbox):
    MEM.clear()
    MEM.data["initial_state"] = {
        "phase": "APPROACH",
        "t": 0,
        "lx": None,
        "ly": None,
        "vx": 0.0,
        "vy": 0.0,
        "unlock_steps": 0,
    }
    return sandbox.get_agent_body()

def agent_action(sandbox, agent_body, step_count):
    state = MEM.data["initial_state"]
    pd = sandbox.get_agent_position()
    vel = sandbox.get_agent_velocity()
    x, y = pd
    vxd, vyd = vel
    front, up, down = sandbox.get_whisker_readings()
    weight_comp = _weight_comp(sandbox)
    cfg = _control_cfg(sandbox)

    if state["phase"] == "APPROACH":
        # Check whisker proximity
        if front < 0.5:
            # Apply lateral force to move away from wall
            fx = 0.0
            fy = 50.0  # Upward force to avoid wall contact
        else:
            # Apply forward force
            if x < 5.0:
                fx = 150.0  # High initial force to push past the wall
            else:
                fx = 80.0 * (7.0 - x) - 5.0 * vxd  # Adjust based on position
            fy = 50.0 * (1.5 - y) - 20.0 * vyd + weight_comp

        # Check if entered activation zone
        if cfg["act_lo"] <= x <= cfg["act_hi"]:
            state["phase"] = "UNLOCK"
            state["t"] = 0
            state["unlock_steps"] = 0
            # Apply backward force for unlock
            fx = -35.0  # Below -34.0 threshold
            fy = 50.0 * (1.5 - y) - 20.0 * vyd + weight_comp
    elif state["phase"] == "UNLOCK":
        # Check if in activation zone and conditions met
        if cfg["act_lo"] <= x <= cfg["act_hi"]:
            # Check commanded FX and velocity
            if fx < cfg["bfx"] and math.hypot(vxd, vyd) < cfg["bspd"]:
                state["unlock_steps"] += 1
            else:
                state["unlock_steps"] = 0
            if state["unlock_steps"] >= 5:
                state["phase"] = "ESCAPE"
                state["unlock_steps"] = 0
        else:
            state["unlock_steps"] = 0
        # Apply backward force
        fx_cmd = cfg["bfx"] - 1.0  # -35.0 N
        fy_cmd = 50.0 * (1.5 - y) - 20.0 * vyd + weight_comp

        # Adjust for velocity
        spd = math.hypot(vxd, vyd)
        if spd >= cfg["bspd"] * 0.99:
            horiz = -1.5 * vxd
            if horiz > 0:
                horiz = 0
            fx_cmd += horiz
            fy_cmd -= 1.5 * vyd

        fx, fy = fx_cmd, fy_cmd
        state["t"] += 1
    elif state["phase"] == "ESCAPE":
        # Forward force to reach exit
        fx = 15.0
        fy = 50.0 * (1.5 - y) - 20.0 * vyd + weight_comp
        if x > _exit_x_min(sandbox) + 2.5:
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        fx, fy = 0.0, weight_comp

    sandbox.apply_agent_force(fx, fy)
